data_portfolio_csv_exchange_error_codes_v1<-function()c(
  "data_portfolio_csv_exchange_invalid","data_portfolio_csv_exchange_worker_unavailable",
  "data_portfolio_csv_exchange_preview_required","data_portfolio_csv_exchange_confirmation_required",
  "data_portfolio_csv_exchange_confirmation_consumed","data_portfolio_csv_exchange_boundary_failed"
)
.data_portfolio_csv_exchange_condition<-function(code){if(!is.character(code)||length(code)!=1L||is.na(code)||(!code%in%data_portfolio_csv_exchange_error_codes_v1()&&!grepl("^portfolio_csv_[a-z_]+$",code)))stop("unregistered_data_portfolio_csv_exchange_error",call.=FALSE);structure(list(message=code,call=NULL,code=code),class=c("spot_data_portfolio_csv_exchange_error","error","condition"))}
.data_portfolio_csv_exchange_abort<-function(code)stop(.data_portfolio_csv_exchange_condition(code))
.data_portfolio_csv_exchange_context<-function(context){if(!isTRUE(tryCatch(runtime_context_valid(context),error=function(error)FALSE))||!identical(context$runtime_mode,"desktop_product")||!identical(context$role,"desktop_owner")||!identical(context$actor_id,"desktop_owner")) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_invalid");context}
.data_portfolio_csv_exchange_run<-function(service,command,payload){
  python<-Sys.which("python3");script<-file.path(service$project_root,"scripts","portfolio_csv_exchange.py")
  if(!nzchar(python)||!file.exists(script)||dir.exists(script)||nzchar(Sys.readlink(script))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable")
  encoded<-as.character(jsonlite::toJSON(payload,auto_unbox=TRUE,null="null",na="null",digits=NA,pretty=FALSE));if(nchar(encoded,type="bytes")>32000000L) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_boundary_failed")
  stderr_dir<-tempfile("portelyra-portfolio-exchange-stderr-");if(!isTRUE(dir.create(stderr_dir,mode="0700"))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable");Sys.chmod(stderr_dir,"0700");on.exit(unlink(stderr_dir,recursive=TRUE,force=TRUE),add=TRUE)
  stderr_path<-file.path(stderr_dir,"stderr");if(!isTRUE(file.create(stderr_path))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable");Sys.chmod(stderr_path,"0600")
  output<-tryCatch(suppressWarnings(system2(python,c("-B","-E","-s",shQuote(script),shQuote(command)),input=encoded,stdout=TRUE,stderr=stderr_path,env="PYTHONDONTWRITEBYTECODE=1")),error=function(error)structure(character(),status=1L));status<-attr(output,"status");if(is.null(status))status<-0L
  stderr_size<-if(file.exists(stderr_path))file.info(stderr_path)$size else NA_real_;one_line<-length(output)==1L&&!is.na(output[[1L]])&&nchar(output[[1L]],type="bytes")<=32000000L
  value<-if(one_line&&isTRUE(!is.na(stderr_size)&&stderr_size==0))tryCatch(jsonlite::fromJSON(output[[1L]],simplifyVector=FALSE),error=function(error)NULL)else NULL
  if(!is.list(value)||is.null(names(value))||!is.character(value$status)||length(value$status)!=1L||is.na(value$status)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable")
  if(status!=0L||value$status%in%c("blocked","failed")) .data_portfolio_csv_exchange_abort(if(is.character(value$code)&&length(value$code)==1L&&!is.na(value$code))value$code else "data_portfolio_csv_exchange_boundary_failed")
  value
}
.data_portfolio_csv_exchange_payload<-function(service,extra=list())c(list(
  context=list(tenant_id=service$context$tenant_id,user_id=service$context$user_id,data_space_id=service$context$data_space_id,actor_id="desktop_owner",role="desktop_owner"),
  data_space_path=runtime_data_space_path(service$context),canonical_path=runtime_canonical_path(service$context)
),extra)
.data_portfolio_csv_handoff_run<-function(service,command,payload){
  python<-Sys.which("python3");script<-file.path(service$project_root,"scripts","portfolio_csv_handoff.py")
  if(!nzchar(python)||!file.exists(script)||dir.exists(script)||nzchar(Sys.readlink(script))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable")
  encoded<-as.character(jsonlite::toJSON(payload,auto_unbox=TRUE,null="null",na="null",digits=NA,pretty=FALSE));if(nchar(encoded,type="bytes")>32000000L) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_boundary_failed")
  stderr_dir<-tempfile("portelyra-portfolio-handoff-stderr-");if(!isTRUE(dir.create(stderr_dir,mode="0700"))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable");Sys.chmod(stderr_dir,"0700");on.exit(unlink(stderr_dir,recursive=TRUE,force=TRUE),add=TRUE)
  stderr_path<-file.path(stderr_dir,"stderr");if(!isTRUE(file.create(stderr_path))) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable");Sys.chmod(stderr_path,"0600")
  output<-tryCatch(suppressWarnings(system2(python,c("-B","-E","-s",shQuote(script),command),input=encoded,stdout=TRUE,stderr=stderr_path,env="PYTHONDONTWRITEBYTECODE=1")),error=function(error)structure(character(),status=1L));status<-attr(output,"status");if(is.null(status))status<-0L
  stderr_size<-if(file.exists(stderr_path))file.info(stderr_path)$size else NA_real_;one_line<-length(output)==1L&&!is.na(output[[1L]])&&nchar(output[[1L]],type="bytes")<=32000000L
  value<-if(one_line&&isTRUE(!is.na(stderr_size)&&stderr_size==0))tryCatch(jsonlite::fromJSON(output[[1L]],simplifyVector=FALSE),error=function(error)NULL)else NULL
  if(!is.list(value)||is.null(names(value))||!is.character(value$status)||length(value$status)!=1L||is.na(value$status)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_worker_unavailable")
  if(status!=0L||value$status%in%c("blocked","failed")) .data_portfolio_csv_exchange_abort(if(is.character(value$code)&&length(value$code)==1L&&!is.na(value$code))value$code else "data_portfolio_csv_exchange_boundary_failed")
  value
}
.data_portfolio_csv_exchange_ref<-function(prefix)paste0(prefix,paste(format(openssl::rand_bytes(16L)),collapse=""))
.data_portfolio_csv_exchange_now<-function()format(as.POSIXct(Sys.time(),tz="UTC"),"%Y-%m-%dT%H:%M:%SZ",tz="UTC")
.data_portfolio_csv_exchange_expiry<-function(now)format(as.POSIXct(now,"%Y-%m-%dT%H:%M:%SZ",tz="UTC")+300,"%Y-%m-%dT%H:%M:%SZ",tz="UTC")
.data_portfolio_csv_exchange_domain<-function(domain){values<-c(catalog="catalog",coupled_transaction="transaction",asset_activity="activity",cash_coverage="cash");if(!is.character(domain)||length(domain)!=1L||is.na(domain)||!domain%in%names(values)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_invalid");unname(values[[domain]])}
new_data_portfolio_csv_exchange_v1<-function(project_root,context){
  service<-new.env(hash=FALSE,parent=emptyenv());service$project_root<-normalizePath(project_root,winslash="/",mustWork=TRUE);service$context<-.data_portfolio_csv_exchange_context(context);service$export_preview<-NULL;service$import_preview<-NULL;service$handoff_previews<-new.env(hash=TRUE,parent=emptyenv());service$recovery_preview<-NULL
  service$paths<-function().data_portfolio_csv_exchange_run(service,"paths",.data_portfolio_csv_exchange_payload(service))
  service$initialize<-function().data_portfolio_csv_exchange_run(service,"initialize",.data_portfolio_csv_exchange_payload(service))
  service$export_prepare<-function(){value<-.data_portfolio_csv_exchange_run(service,"export-preview",.data_portfolio_csv_exchange_payload(service));service$export_preview<-list(public=value$preview,consumed=FALSE);value$preview}
  service$export_execute<-function(confirmed){if(!isTRUE(confirmed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_required");if(is.null(service$export_preview)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_preview_required");if(isTRUE(service$export_preview$consumed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_consumed");service$export_preview$consumed<-TRUE;value<-.data_portfolio_csv_exchange_run(service,"export-apply",.data_portfolio_csv_exchange_payload(service,list(bundle_handle=service$export_preview$public$bundle_handle,confirmed=TRUE)));service$export_preview<-NULL;value$result}
  service$import_list<-function().data_portfolio_csv_exchange_run(service,"import-list",.data_portfolio_csv_exchange_payload(service))
  service$import_prepare<-function(bundle_handle){if(!is.character(bundle_handle)||length(bundle_handle)!=1L||is.na(bundle_handle)||!grepl("^pcb_[a-f0-9]{24}$",bundle_handle)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_invalid");value<-.data_portfolio_csv_exchange_run(service,"import-preview",.data_portfolio_csv_exchange_payload(service,list(bundle_handle=bundle_handle)));service$import_preview<-list(public=value$preview,consumed=FALSE);value$preview}
  service$import_execute<-function(confirmed){if(!isTRUE(confirmed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_required");if(is.null(service$import_preview)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_preview_required");if(isTRUE(service$import_preview$consumed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_consumed");service$import_preview$consumed<-TRUE;value<-.data_portfolio_csv_exchange_run(service,"import-apply",.data_portfolio_csv_exchange_payload(service,list(bundle_handle=service$import_preview$public$bundle_handle,confirmed=TRUE)));service$import_preview<-NULL;value$result}
  service$staged_imports<-function().data_portfolio_csv_handoff_run(service,"staged-imports",list(context=.data_portfolio_csv_exchange_payload(service)$context,data_space_path=runtime_data_space_path(service$context)))
  service$handoff_prepare<-function(domain,staged_import_handle){command<-.data_portfolio_csv_exchange_domain(domain);if(!is.character(staged_import_handle)||length(staged_import_handle)!=1L||is.na(staged_import_handle)||!grepl("^imp_[a-f0-9]{24}$",staged_import_handle)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_invalid");value<-.data_portfolio_csv_handoff_run(service,paste0(command,"-preview"),.data_portfolio_csv_exchange_payload(service,list(staged_import_handle=staged_import_handle)));assign(domain,list(public=value$public_preview,trusted=value$trusted_preview,consumed=FALSE),envir=service$handoff_previews);value$public_preview}
  service$handoff_execute<-function(domain,confirmed){command<-.data_portfolio_csv_exchange_domain(domain);if(!exists(domain,envir=service$handoff_previews,inherits=FALSE)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_preview_required");entry<-get(domain,envir=service$handoff_previews,inherits=FALSE);if(!isTRUE(confirmed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_required");if(isTRUE(entry$consumed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_consumed");entry$consumed<-TRUE;assign(domain,entry,envir=service$handoff_previews);now<-.data_portfolio_csv_exchange_now();authority<-.data_portfolio_csv_handoff_run(service,paste0(command,"-confirmation"),list(context=.data_portfolio_csv_exchange_payload(service)$context,trusted_preview=entry$trusted,confirmation_ref=.data_portfolio_csv_exchange_ref("pchc_"),issued_at_utc=now,expires_at_utc=.data_portfolio_csv_exchange_expiry(now)))$confirmation;value<-.data_portfolio_csv_handoff_run(service,paste0(command,"-apply"),.data_portfolio_csv_exchange_payload(service,list(trusted_preview=entry$trusted,confirmation=authority,applied_at_utc=now)));rm(list=domain,envir=service$handoff_previews);value$result}
  service$handoff_recovery_candidates<-function().data_portfolio_csv_handoff_run(service,"recovery-candidates",list(context=.data_portfolio_csv_exchange_payload(service)$context,data_space_path=runtime_data_space_path(service$context)))
  service$handoff_recovery_prepare<-function(recovery_ref){if(!is.character(recovery_ref)||length(recovery_ref)!=1L||is.na(recovery_ref)||!grepl("^portfolio_handoff_recovery_[a-f0-9]{32}$",recovery_ref)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_invalid");value<-.data_portfolio_csv_handoff_run(service,"recovery-preview",.data_portfolio_csv_exchange_payload(service,list(recovery_ref=recovery_ref)));service$recovery_preview<-list(public=value$public_preview,trusted=value$trusted_preview,consumed=FALSE);value$public_preview}
  service$handoff_recovery_execute<-function(confirmed){entry<-service$recovery_preview;if(is.null(entry)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_preview_required");if(!isTRUE(confirmed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_required");if(isTRUE(entry$consumed)) .data_portfolio_csv_exchange_abort("data_portfolio_csv_exchange_confirmation_consumed");entry$consumed<-TRUE;service$recovery_preview<-entry;now<-.data_portfolio_csv_exchange_now();authority<-.data_portfolio_csv_handoff_run(service,"recovery-confirmation",list(context=.data_portfolio_csv_exchange_payload(service)$context,trusted_recovery_preview=entry$trusted,confirmation_ref=.data_portfolio_csv_exchange_ref("pchr_"),issued_at_utc=now,expires_at_utc=.data_portfolio_csv_exchange_expiry(now)))$confirmation;value<-.data_portfolio_csv_handoff_run(service,"recovery-apply",.data_portfolio_csv_exchange_payload(service,list(trusted_recovery_preview=entry$trusted,recovery_confirmation=authority,recovered_at_utc=now)));service$recovery_preview<-NULL;value$result}
  service$cash_candidates<-function(staged_import_handle).data_portfolio_csv_handoff_run(service,"cash-candidates",.data_portfolio_csv_exchange_payload(service,list(staged_import_handle=staged_import_handle)))
  service$cash_candidate<-function(staged_import_handle,candidate_ref).data_portfolio_csv_handoff_run(service,"cash-candidate",.data_portfolio_csv_exchange_payload(service,list(staged_import_handle=staged_import_handle,candidate_ref=candidate_ref)))
  class(service)<-"spot_data_portfolio_csv_exchange_v1";service
}

data_portfolio_csv_exchange_ui_v1<-function(){
