    shiny::div(class="pl-editor-actions",shiny::actionButton("portfolio_exchange_paths","Ordner anzeigen",class="btn-default"),shiny::checkboxInput("portfolio_exchange_initialize_confirm","Austauschordner lokal beim Eigentümer anlegen",FALSE),shiny::actionButton("portfolio_exchange_initialize","Bestätigt anlegen",class="btn-primary")),
    shiny::uiOutput("portfolio_exchange_path_view"),
    shiny::tags$h3("Verlustfreier Export"),
    shiny::p(class="pl-section-copy","Komma als Feldtrenner und Dezimalzeichen; alle Felder sind RFC-4180-gequotet. portfolio.csv enthält jeden aktuellen Datensatz einmal, Assets und Konten/Wallets erhalten redundante selbstständige Dateien."),
    shiny::div(class="pl-editor-actions",shiny::actionButton("portfolio_exchange_export_prepare","Export-Vorschau",class="btn-default"),shiny::checkboxInput("portfolio_exchange_export_confirm","Genau dieses Paket exportieren · nur neu angelegt",FALSE),shiny::actionButton("portfolio_exchange_export_execute","Bestätigt exportieren",class="btn-primary")),
    shiny::uiOutput("portfolio_exchange_export_state"),
    shiny::tags$h3("Verlustfreier Import in den Eingangsordner"),
    shiny::p(class="pl-section-copy","Paketordner in den angezeigten Eingangsordner kopieren. Der Import prüft Prüfsummen, Dezimalwerte und alle redundanten Projektionen und übernimmt das Paket verlustfrei in einen separaten Eingangsordner. Das Schreiben in Katalog und Buchungen braucht danach jeweils eine eigene Bestätigung."),
    shiny::div(class="pl-form-grid",shiny::selectInput("portfolio_exchange_import_bundle","Paket",c("Bitte Eingangsordner lesen"=""))),
    shiny::div(class="pl-editor-actions",shiny::actionButton("portfolio_exchange_import_refresh","Eingangsordner lesen",class="btn-default"),shiny::actionButton("portfolio_exchange_import_prepare","Import-Vorschau",class="btn-default"),shiny::checkboxInput("portfolio_exchange_import_confirm","Genau dieses geprüfte Paket in den Eingangsordner übernehmen",FALSE),shiny::actionButton("portfolio_exchange_import_execute","Bestätigt importieren",class="btn-primary")),
