    shiny::div(class="pl-form-grid",shiny::selectInput("portfolio_exchange_staged_import","Vorgemerktes Paket",c("Noch nicht gelesen"="")),shiny::selectInput("portfolio_exchange_handoff_domain","Bereich",c("Katalog"="catalog","Gekoppelte Transaktionen"="coupled_transaction","Buchungsentwürfe"="asset_activity","Cash-Vorschläge zur Prüfung"="cash_coverage"))),
    shiny::div(class="pl-editor-actions",shiny::actionButton("portfolio_exchange_staged_refresh","Vorgemerkte Pakete lesen",class="btn-default"),shiny::actionButton("portfolio_exchange_handoff_prepare","Vorschau für den Bereich",class="btn-default"),shiny::checkboxInput("portfolio_exchange_handoff_confirm","Genau diesen Plan für den Bereich einmal ausführen",FALSE),shiny::actionButton("portfolio_exchange_handoff_execute","Bestätigte Übergabe ausführen",class="btn-primary")),
    shiny::uiOutput("portfolio_exchange_handoff_state"),
    shiny::tags$h3("Unterbrochene Übergabe wieder aufnehmen"),
    shiny::div(class="pl-form-grid",shiny::selectInput("portfolio_exchange_recovery_candidate","Unterbrochene Übergabe eines Bereichs",c("Noch nicht gelesen"=""))),
    shiny::div(class="pl-editor-actions",shiny::actionButton("portfolio_exchange_recovery_refresh","Kandidaten für die Wiederaufnahme lesen",class="btn-default"),shiny::actionButton("portfolio_exchange_recovery_prepare","Vorschau der Wiederaufnahme",class="btn-default"),shiny::checkboxInput("portfolio_exchange_recovery_confirm","Genau diesen abgestimmten Versuch wieder aufnehmen",FALSE),shiny::actionButton("portfolio_exchange_recovery_execute","Bestätigte Wiederaufnahme",class="btn-primary")),
    shiny::uiOutput("portfolio_exchange_recovery_state"),
    shiny::tags$h3("Cash-Vorschläge an die Cash-Prüfung übergeben"),
